 static int[] SelectIds(IEnumerable<Registry> registries){
  var rows=registries.Where(r=>r.Containers).SelectMany(r=>r.Rows).ToArray();
  var used=new HashSet<int>(rows.Select(PositiveId).Where(id=>id>0));
  int max=used.Count==0?0:used.Max();var selected=new int[LayoutIds.Length];
  for(int layout=0;layout<LayoutIds.Length;layout++){
   var ours=new HashSet<int>(rows.Where(r=>r.Own&&r.Layout==layout).Select(PositiveId).Where(id=>id>0));
   var occupied=new HashSet<int>(rows.Where(r=>!r.Own||r.Layout!=layout).Select(PositiveId).Where(id=>id>0));
   var keep=ours.Where(id=>!occupied.Contains(id)&&!selected.Contains(id)).ToArray();
   if(keep.Length==1){selected[layout]=keep[0];continue;}
   Need(max<Int32.MaxValue,"No positive numeric layout ID is available above the recipient's existing IDs.");
