 static void CheckSpace(Plan p,Action<string> log){var requirements=new Dictionary<string,long>(StringComparer.OrdinalIgnoreCase);Action<string,long> add=(path,count)=>{string drive=Path.GetPathRoot(PhysicalPath(path));if(!requirements.ContainsKey(drive))requirements[drive]=0;requirements[drive]=checked(requirements[drive]+count);};foreach(var f in p.Files.Where(f=>f.Changed)){add(f.Target,f.AfterLength);if(f.Existed)add(p.Game,f.BeforeLength);}add(p.Game,2L*FooterSize+p.Tables.Sum(t=>(long)t.Before.Length+t.After.Length)+Math.Max(0,p.FinalLength-p.OriginalLength)+16*1024*1024);foreach(var r in requirements){try{var drive=new DriveInfo(r.Key);Need(drive.IsReady&&AvailableSpace(drive)>=r.Value,"Insufficient free disk space on "+r.Key+"; requires approximately "+(r.Value/1024/1024+1)+" MiB.");}catch(ArgumentException){Log(p.Report,log,"Free-space reporting is unavailable for "+r.Key+"; writes remain subject to filesystem capacity.");}}}
