 static Report ExecuteCore(string game,string mods,string payloadRoot,string activeMods,Action<string> log,bool apply){BeginLinks();Closed();game=RootPath(game);mods=RootPath(mods);activeMods=RootPath(activeMods);payloadRoot=RootPath(payloadRoot);Need(Directory.Exists(game),"Select the installed EVO game folder.");string packagePath=Within(game,"content.kspkg");Need(File.Exists(packagePath),"The selected game folder does not contain content.kspkg.");RefuseIncomplete(game);using(var package=new FileStream(packagePath,FileMode.Open,apply?FileAccess.ReadWrite:FileAccess.Read,FileShare.None)){Plan p=BuildPlan(game,mods,payloadRoot,activeMods,package,log);ValidateLinks();LinksFrozen=true;if(!apply){p.Report.Success=true;Log(p.Report,log,"Read-only check completed. Nothing changed.");return p.Report;}foreach(var f in p.Files)Current(f);ValidateAdditionalState(activeMods);ValidateTrackSnapshot(p);ValidateProductSnapshot(p);ValidateMount(p.Mount);AssertPackage(package,p);Closed();if(!p.PackageChanged&&p.Files.All(f=>!f.Changed)&&(p.Mount==null||!p.Mount.Needed)){p.Report.Success=true;p.Report.Applied=true;Log(p.Report,log,"The complete firstpass01 installation is already current.");return p.Report;}
   string backup=Within(game,"HDC_Backups/The_Yard_Lineup_1.4_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss_fff")+"_"+Guid.NewGuid().ToString("N").Substring(0,8));var backupDirs=new List<string>();EnsureDirectory(backup,backupDirs);p.Report.BackupPath=backup;EnsureDirectory(Path.Combine(backup,"files"),backupDirs);EnsureDirectory(Path.Combine(backup,"package"),backupDirs);DurableBytes(Path.Combine(backup,"package/footer.before"),p.Footer);DurableBytes(Path.Combine(backup,"package/footer.after"),p.NewFooter);for(int i=0;i<p.Tables.Count;i++){DurableBytes(Path.Combine(backup,"package/table"+i+".before"),p.Tables[i].Before);DurableBytes(Path.Combine(backup,"package/table"+i+".after"),p.Tables[i].After);}var changed=p.Files.Where(f=>f.Changed).ToList();for(int i=0;i<changed.Count;i++){var f=changed[i];Current(f);if(f.Existed){f.Backup=Path.Combine(backup,"files/"+i+".before");CopyDurable(f.Target,f.Backup);Need(HashFile(f.Backup)==f.BeforeHash,"Backup verification failed: "+f.Relative);}}
   var journal=new List<string>{"Format=HDCStandalone1","State=prepared","Game="+game,"Mods="+mods,"ActiveMods="+activeMods,"Package="+packagePath,"OriginalLength="+p.OriginalLength,"OriginalFooterOffset="+p.FooterStart,"OriginalFooterSha256="+Hash(p.Footer),"IntendedFooterSha256="+Hash(p.NewFooter),"FinalLength="+p.FinalLength,"PackageMode="+p.Report.PackageMode,"BackendId="+p.Report.BackendId,"BackendIds="+String.Join(",",p.Report.BackendIds.Select(pair=>pair.Key+":"+pair.Value)),"FilesStarted=0","PackageStarted=false","MountStarted=false","MountNeeded="+(p.Mount!=null&&p.Mount.Needed),"MountPath="+(p.Mount==null?"-":p.Mount.Path),"MountTarget="+(p.Mount==null?"-":p.Mount.Target),"MountBackup="+(p.Mount==null?"-":p.Mount.Backup),"MountOriginal="+(p.Mount==null?"none":p.Mount.OriginalKind),"MountFingerprint="+(p.Mount==null?"-":p.Mount.Fingerprint)};for(int i=0;i<p.Tables.Count;i++){var t=p.Tables[i];journal.Add("Table="+i+"|"+t.Name+"|"+t.Offset+"|"+t.Size+"|"+t.Entry+"|"+Hash(t.Before)+"|"+Hash(t.After)+"|"+t.NewOffset+"|"+t.After.Length);}for(int i=0;i<changed.Count;i++){var f=changed[i];journal.Add("File="+i+"|"+(f.Root==game?"game":f.Root==mods?"mods":"active")+"|"+f.Relative+"|"+(f.Existed?"REPLACED":"NEW")+"|"+(f.BeforeHash??"-")+"|"+f.AfterHash);}foreach(var pin in LinkPins)journal.Add("DirectoryLink="+pin.Key+"|"+pin.Value);string journalFile=Path.Combine(backup,"recovery.txt");SaveJournal(journalFile,journal);Log(p.Report,log,"Backups saved. Installing track files...");AssertPackage(package,p);ValidateTrackSnapshot(p);ValidateProductSnapshot(p);Closed();var written=new List<FilePlan>();var created=new List<string>();bool packageTouched=false,mountTouched=false;
   try{for(int i=0;i<changed.Count;i++){var f=changed[i];Current(f);EnsureDirectory(Path.GetDirectoryName(f.Target),created);SaveProgress(journalFile,journal,"FilesStarted",(i+1).ToString());written.Add(f);InstallFile(f);Need(InstalledMatches(f),"Installed file verification failed: "+f.Relative);if((i+1)%100==0)Log(p.Report,log,"Verified "+(i+1)+" of "+changed.Count+" changed files.");}
    if(p.Mount!=null&&p.Mount.Needed){SaveProgress(journalFile,journal,"MountStarted","true");mountTouched=true;PublishMount(p.Mount,created);Log(p.Report,log,"The Yard is mounted from the selected folder.");}if(p.PackageChanged){AssertPackage(package,p);SaveProgress(journalFile,journal,"PackageStarted","true");packageTouched=true;Log(p.Report,log,"Writing scoped track registrations...");foreach(var t in p.Tables)Write(package,t.NewOffset,t.After);Write(package,p.NewFooterStart,p.NewFooter);package.Flush(true);Need(package.Length==p.FinalLength,"Unexpected package length after registration.");Need(Read(package,p.NewFooterStart,FooterSize).SequenceEqual(p.NewFooter),"Package directory verification failed.");foreach(var t in p.Tables)Need(Read(package,t.NewOffset,t.After.Length).SequenceEqual(t.After),"Registered table verification failed.");if(p.Append){Need(Read(package,p.FooterStart,FooterSize).SequenceEqual(p.Footer),"Original package footer changed during append.");foreach(var t in p.Tables)Need(Read(package,t.Offset,t.Size).SequenceEqual(t.Before),"Original table changed during append.");}else foreach(var t in p.Tables)Need(Read(package,t.Offset+t.After.Length,t.Size-t.After.Length).SequenceEqual(Slice(t.Before,t.After.Length,t.Size-t.After.Length)),"Package table slack changed.");}
    foreach(var f in changed)Need(InstalledMatches(f),"Final installed-file verification failed: "+f.Relative);ValidateInstalledTrack(p);ValidateProductInstalled(p);journal[1]="State=complete";SaveJournal(journalFile,journal);p.Report.Success=true;p.Report.Applied=true;Log(p.Report,log,"The Yard firstpass01 is installed and verified. Backup: "+backup);return p.Report;
   }catch(Exception failure){var errors=new List<string>();if(packageTouched)try{if(p.Append)package.SetLength(p.OriginalLength);else{foreach(var t in p.Tables)Write(package,t.Offset,t.Before);Write(package,p.FooterStart,p.Footer);package.SetLength(p.OriginalLength);}package.Flush(true);AssertPackage(package,p);}catch(Exception e){errors.Add("Package: "+e.Message);}if(mountTouched)try{RestoreMount(p.Mount);}catch(Exception e){errors.Add("Track mount: "+e.Message);}foreach(var f in written.AsEnumerable().Reverse())try{ValidateRollbackFile(f);CheckReparse(f.Target);if(f.Existed){Need(f.Backup!=null&&HashFile(f.Backup)==f.BeforeHash,"Backup checksum mismatch.");RestoreFile(f);Need(HashFile(f.Target)==f.BeforeHash,"Restored file checksum mismatch.");}else if(File.Exists(f.Target))File.Delete(f.Target);RemoveTemporary(f.Target);}catch(Exception e){errors.Add(f.Relative+": "+e.Message);}foreach(string dir in created.AsEnumerable().Reverse())try{CheckReparse(dir);if(Directory.Exists(dir)&&!Directory.EnumerateFileSystemEntries(dir).Any())Directory.Delete(dir,false);}catch(Exception e){errors.Add("Directory recovery: "+e.Message);}journal[1]=errors.Count==0?"State=rolled_back":"State=recovery_required";try{journal.Add("Failure="+failure.Message.Replace('\r',' ').Replace('\n',' '));SaveJournal(journalFile,journal);}catch(Exception e){errors.Add("Recovery journal: "+e.Message);}throw new InvalidOperationException(errors.Count==0?"Installation failed; all installation changes were rolled back. "+failure.Message+" Backup: "+backup:"Installation failed and recovery needs attention. "+failure.Message+" Recovery: "+String.Join("; ",errors)+" Backup: "+backup,failure);}
