 static void SaveProgress(string path,List<string> journal,string key,string value){int index=journal.FindIndex(s=>s.StartsWith(key+"=",StringComparison.Ordinal));Need(index>=0,"Recovery journal field missing.");journal[index]=key+"="+value;SaveJournal(path,journal);}
 static void SaveJournal(string path,List<string> journal){string temporary=path+".next";CheckReparse(temporary);DurableBytes(temporary,Encoding.UTF8.GetBytes(String.Join("\r\n",journal)+"\r\n"));for(int attempt=0;;attempt++){try{if(File.Exists(path))File.Replace(temporary,path,null);else File.Move(temporary,path);break;}catch(IOException e){int code=Marshal.GetHRForException(e)&0xffff;if((code!=32&&code!=33)||attempt>=7)throw;System.Threading.Thread.Sleep(25*(attempt+1));}}}
