 static void RefuseIncomplete(string game){string root=Within(game,"HDC_Backups");if(!Directory.Exists(root))return;foreach(string folder in Directory.GetDirectories(root,"The_Yard_*")){CheckReparse(folder);string file=Path.Combine(folder,"recovery.txt");if(!File.Exists(file))continue;CheckReparse(file);string[] journal=File.ReadAllLines(file);if(!journal.Contains("Format=HDCStandalone1"))continue;string state=JournalValue(journal,"State");Need(state=="complete"||state=="rolled_back","An incomplete Akagi installation requires recovery before another check or install. Use Recover with this backup folder: "+folder);}}
 // Explicit recovery is restricted to an unfinished journal for the selected
 // game and mods folders. It restores only destinations marked as started.
