  BeginLinks();Closed();game=RootPath(game);mods=RootPath(mods);activeMods=RootPath(activeMods);backupPath=RootPath(backupPath);
  Need(Under(backupPath,Within(game,"HDC_Backups")),"Recovery backup must be inside the selected game's HDC_Backups folder.");
  string journalPath=Within(backupPath,"recovery.txt");string[] lines=File.ReadAllLines(journalPath);
  Need(JournalValue(lines,"Format")=="HDCStandalone1","Unsupported recovery journal.");LoadLinkPins(lines);
  string state=JournalValue(lines,"State");Need(state=="prepared"||state=="recovery_required"||state=="complete","This backup has already been rolled back or has an unsupported state.");
  Need(RootPath(JournalValue(lines,"Game")).Equals(game,StringComparison.OrdinalIgnoreCase)&&RootPath(JournalValue(lines,"Mods")).Equals(mods,StringComparison.OrdinalIgnoreCase),"Recovery folders do not match the original installation.");
  Need(RootPath(JournalValue(lines,"ActiveMods")).Equals(activeMods,StringComparison.OrdinalIgnoreCase),"The active mods folder does not match the interrupted installation.");bool mountStarted=Boolean.Parse(JournalValue(lines,"MountStarted"));MountPlan mount=RecoveryMount(lines,mods,activeMods);Need(!mountStarted||(mount!=null&&mount.Needed),"Invalid mount progress marker.");if(mountStarted)ValidateRecoverMount(mount);string packagePath=Within(game,"content.kspkg");Need(Path.GetFullPath(JournalValue(lines,"Package")).Equals(packagePath,StringComparison.OrdinalIgnoreCase),"Recovery package path mismatch.");
  long originalLength=Int64.Parse(JournalValue(lines,"OriginalLength")),footerOffset=Int64.Parse(JournalValue(lines,"OriginalFooterOffset")),finalLength=Int64.Parse(JournalValue(lines,"FinalLength"));
  Need(originalLength>FooterSize&&footerOffset==originalLength-FooterSize&&finalLength>=originalLength,"Invalid recovery package lengths.");
  int started=Int32.Parse(JournalValue(lines,"FilesStarted"));bool packageStarted=Boolean.Parse(JournalValue(lines,"PackageStarted")),append=finalLength>originalLength;
  byte[] footer=File.ReadAllBytes(Within(backupPath,"package/footer.before")),intendedFooter=File.ReadAllBytes(Within(backupPath,"package/footer.after"));
  Need(footer.Length==FooterSize&&Hash(footer)==JournalValue(lines,"OriginalFooterSha256")&&intendedFooter.Length==FooterSize&&Hash(intendedFooter)==JournalValue(lines,"IntendedFooterSha256"),"Recovery footer checksum mismatch.");
  byte[] decoded=Xor(footer),expectedFooter=(byte[])footer.Clone();var tables=new List<NativeTable>();var tableIndices=new HashSet<int>();long nextOffset=originalLength;
  foreach(string line in lines.Where(s=>s.StartsWith("Table=",StringComparison.Ordinal))){
   string[] parts=line.Substring(6).Split('|');Need(parts.Length==9,"Invalid recovery table record.");
   int index=Int32.Parse(parts[0]),size=Int32.Parse(parts[3]),entry=Int32.Parse(parts[4]),afterLength=Int32.Parse(parts[8]);long offset=Int64.Parse(parts[2]),newOffset=Int64.Parse(parts[7]);
   Need(index>=0&&index<2&&tableIndices.Add(index)&&size>0&&size<=MaximumTableSize&&afterLength>0&&afterLength<=MaximumTableSize&&entry>=0&&entry<=FooterSize-256&&entry%256==0&&offset>=0&&offset<=footerOffset-size,"Invalid recovery table extent.");
   Need(parts[1]=="system/tracks.table"||parts[1]=="system/track_containers.table","Unexpected recovery table identity.");
   int nameLength=BitConverter.ToUInt16(decoded,entry+230);Need(nameLength>0&&nameLength<=224&&Normalize(new UTF8Encoding(false,true).GetString(decoded,entry,nameLength))==parts[1]&&BitConverter.ToInt64(decoded,entry+240)==size&&BitConverter.ToInt64(decoded,entry+248)==offset,"Recovery table does not match the saved directory.");
   byte[] before=File.ReadAllBytes(Within(backupPath,"package/table"+index+".before")),after=File.ReadAllBytes(Within(backupPath,"package/table"+index+".after"));
   Need(before.Length==size&&Hash(before)==parts[5]&&after.Length==afterLength&&Hash(after)==parts[6],"Recovery table checksum mismatch.");
   Need(append?newOffset==nextOffset:newOffset==offset&&afterLength<=size,"Invalid intended table placement.");if(append)nextOffset=checked(nextOffset+afterLength);
   byte[] sizeBytes=BitConverter.GetBytes((long)afterLength),offsetBytes=BitConverter.GetBytes(newOffset);for(int i=0;i<8;i++){expectedFooter[entry+240+i]=(byte)(sizeBytes[i]^Key[i]);expectedFooter[entry+248+i]=(byte)(offsetBytes[i]^Key[i]);}
   tables.Add(new NativeTable{Name=parts[1],Offset=offset,Size=size,Entry=entry,Before=before,After=after,NewOffset=newOffset});
  }
  Need(tables.Count==2&&tables.Select(t=>t.Name).Distinct().Count()==2&&tables.Select(t=>t.Entry).Distinct().Count()==2,"Incomplete recovery table records.");
  Need(tables[0].Offset+tables[0].Size<=tables[1].Offset||tables[1].Offset+tables[1].Size<=tables[0].Offset,"Overlapping recovery tables.");
  Need(expectedFooter.SequenceEqual(intendedFooter)&&(!append||checked(nextOffset+FooterSize)==finalLength),"Intended recovery directory does not match this transaction.");
  var outputs=new List<FilePlan>();var indices=new HashSet<int>();
  foreach(string line in lines.Where(s=>s.StartsWith("File=",StringComparison.Ordinal))){
   string[] parts=line.Substring(5).Split('|');Need(parts.Length==6,"Invalid recovery file record.");int index=Int32.Parse(parts[0]);Need(index>=0&&indices.Add(index),"Duplicate recovery file record.");
   Need(parts[1]=="game"||parts[1]=="mods"||parts[1]=="active","Invalid recovery destination root.");string root=parts[1]=="game"?game:parts[1]=="mods"?mods:activeMods;string rel=SafeRelative(parts[2]);
