   Need(permitted,"Unexpected recovery destination.");Need(parts[3]=="NEW"||parts[3]=="REPLACED","Invalid recovery file state.");Need(parts[5]=="-"||Regex.IsMatch(parts[5],"^[0-9a-f]{64}$"),"Invalid recovery destination checksum.");Need(parts[5]!="-"||(parts[3]=="REPLACED"&&RecoveryOwned(backupPath,index,parts[1],rel,parts[3],parts[5],mods,activeMods)),"Invalid obsolete-file recovery record.");if(index>=started)continue;
   var f=new FilePlan{Root=root,Relative=rel,Target=Within(root,rel),Existed=parts[3]=="REPLACED",BeforeHash=parts[4],AfterHash=parts[5],Delete=parts[5]=="-"};
   CheckReparse(f.Target+".akagi-firstpass01-installing");Need(!Directory.Exists(f.Target)&&!Directory.Exists(f.Target+".akagi-firstpass01-installing"),"A directory occupies a recovery file destination.");
   if(f.Existed){Need(Regex.IsMatch(f.BeforeHash,"^[0-9a-f]{64}$"),"Invalid recovery backup checksum.");f.Backup=Within(backupPath,"files/"+index+".before");Need(File.Exists(f.Backup)&&HashFile(f.Backup)==f.BeforeHash,"Recovery file backup checksum mismatch: "+rel);Need(f.Delete||File.Exists(f.Target),"A pre-existing destination was removed after interruption; recovery refused: "+rel);}
   else Need(parts[4]=="-","Unexpected backup for a new file.");
   if(File.Exists(f.Target)){string current=HashFile(f.Target);Need(current==f.AfterHash||(f.Existed&&current==f.BeforeHash),"A destination was edited after interruption; recovery refused: "+rel);}
   ValidateRollbackFile(f);outputs.Add(f);
  }
  Need(started>=0&&started<=indices.Count&&indices.OrderBy(i=>i).SequenceEqual(Enumerable.Range(0,indices.Count))&&outputs.Count==started,"Invalid recovery progress marker.");Need(outputs.Select(f=>PhysicalPath(f.Target)).Distinct(StringComparer.OrdinalIgnoreCase).Count()==outputs.Count,"Duplicate recovery destination.");
  var report=new Report{BackupPath=backupPath,OriginalPackageLength=originalLength,FinalPackageLength=originalLength,PackageMode="Recovered",ChangedFileCount=outputs.Count,ObsoleteFileCount=outputs.Count(f=>f.Delete),SelectedMods=mods,ActiveMods=activeMods,MountPath=mount==null?null:mount.Path,MountTarget=mount==null?null:mount.Target,MountBackupPath=mount==null?null:mount.Backup,MountAction=mountStarted?"Restore previous Akagi directory/mount":"Mount unchanged"};
  using(var package=new FileStream(packagePath,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){
   Need(package.Length>=originalLength&&package.Length<=finalLength,"Package length changed outside this incomplete installation; recovery refused.");byte[] currentFooter=Read(package,footerOffset,FooterSize);
   if(append||!packageStarted){Need(currentFooter.SequenceEqual(footer)&&tables.All(t=>Read(package,t.Offset,t.Size).SequenceEqual(t.Before)),"The original package bytes changed after interruption; recovery refused.");}
   else{Need(OriginalOrIntended(currentFooter,footer,intendedFooter),"Package directory changed outside this transaction; recovery refused.");foreach(var t in tables)Need(OriginalOrIntended(Read(package,t.Offset,t.Size),t.Before,t.After),"Package registry changed outside this transaction; recovery refused.");}
   if(append){long cursor=originalLength;foreach(byte[] segment in tables.Select(t=>t.After).Concat(new[]{intendedFooter})){int available=(int)Math.Min(segment.Length,Math.Max(0,package.Length-cursor));if(available>0)Need(Read(package,cursor,available).SequenceEqual(Slice(segment,0,available)),"Appended package bytes changed outside this transaction; recovery refused.");cursor=checked(cursor+segment.Length);}}
   Closed();Log(report,log,"Restoring this Akagi installation from verified backups...");
   if(packageStarted){if(append)package.SetLength(originalLength);else{foreach(var t in tables)Write(package,t.Offset,t.Before);Write(package,footerOffset,footer);}package.Flush(true);}
