   if(mountStarted)RestoreMount(mount);var dirs=new List<string>();foreach(var f in outputs.AsEnumerable().Reverse()){CheckReparse(f.Target);if(f.Existed){EnsureDirectory(Path.GetDirectoryName(f.Target),dirs);RestoreFile(f);Need(HashFile(f.Target)==f.BeforeHash,"Restored file checksum mismatch: "+f.Relative);}else if(File.Exists(f.Target))File.Delete(f.Target);RemoveTemporary(f.Target);}
   var journal=lines.ToList();SaveProgress(journalPath,journal,"State","rolled_back");report.Success=true;Log(report,log,"Recovery completed. The previous package and started file destinations are restored.");return report;
  }
