 static MountPlan RecoveryMount(string[] journal,string mods,string active){bool needed=Boolean.Parse(JournalValue(journal,"MountNeeded"));string mountPath=JournalValue(journal,"MountPath");if(mountPath=="-"){Need(!needed,"Missing mount recovery information.");return null;}Need(!mods.Equals(active,StringComparison.OrdinalIgnoreCase),"Unexpected mount for the active mods folder.");string expected=Path.GetFullPath(Path.Combine(active,TrackRoot.Replace('/',Path.DirectorySeparatorChar))),target=PhysicalPath(Within(mods,TrackRoot)),backup=JournalValue(journal,"MountBackup"),kind=JournalValue(journal,"MountOriginal"),fingerprint=JournalValue(journal,"MountFingerprint");Need(Path.GetFullPath(mountPath).Equals(expected,StringComparison.OrdinalIgnoreCase)&&Path.GetFullPath(JournalValue(journal,"MountTarget")).Equals(target,StringComparison.OrdinalIgnoreCase),"Mount recovery paths do not match the selected folders.");Need(Path.GetDirectoryName(backup).Equals(Path.GetDirectoryName(expected),StringComparison.OrdinalIgnoreCase)&&backup.StartsWith(expected+".akagi-firstpass01-backup-",StringComparison.OrdinalIgnoreCase)&&Regex.IsMatch(backup.Substring((expected+".akagi-firstpass01-backup-").Length),"^[0-9a-f]{32}$"),"Unsafe mount backup path.");Need(kind=="none"||kind=="directory"||kind=="junction","Invalid original mount kind.");Need(needed==(kind!="junction"),"Inconsistent mount recovery operation.");Need(kind=="directory"?Regex.IsMatch(fingerprint,"^[0-9a-f]{64}$"):fingerprint=="-","Invalid mount fingerprint.");CheckReparse(Path.GetDirectoryName(expected));CheckReparse(backup);return new MountPlan{Path=expected,Target=target,Backup=backup,OriginalKind=kind,Fingerprint=fingerprint,Needed=needed};}
 public static Report Recover(string game,string mods,string backupPath,Action<string> log){return Recover(game,mods,backupPath,mods,log);}
